<?php
require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../lib/razorpay.php';$pdo=db();$raw=file_get_contents('php://input');$sig=$_SERVER['HTTP_X_RAZORPAY_SIGNATURE']??'';$secret=setting($pdo,'razorpay_webhook_secret');if(!$secret||!razorpay_verify_webhook($raw,$sig,$secret)){http_response_code(401);exit('invalid signature');}$event=json_decode($raw,true);$type=$event['event']??'';$payment=$event['payload']['payment']['entity']??[];$orderId=$payment['order_id']??'';$paymentId=$payment['id']??'';if($orderId){$s=$pdo->prepare('SELECT id FROM orders WHERE razorpay_order_id=? LIMIT 1');$s->execute([$orderId]);$oid=$s->fetchColumn();if($oid){if($type==='payment.captured'){$pdo->prepare("UPDATE orders SET payment_status='paid',razorpay_payment_id=?,payment_reference=? WHERE id=?")->execute([$paymentId,$payment['status']??'captured',$oid]);}elseif($type==='payment.failed'){$pdo->prepare("UPDATE orders SET payment_status='failed' WHERE id=?")->execute([$oid]);}}}http_response_code(200);echo 'ok';
